        "USER_DATA_ENCRYPTION is required, but no .yinshi-encrypted-storage marker "
        f"was found for {tenant.data_dir}. Mount an fscrypt/LUKS/encrypted volume first."
    )


def _open_user_connection(
    db_path: str,
    tenant: TenantContext | None,
